@extends('layouts.business') @section('title','Catalog import & export') @section('content')<div class="page-heading"><div><h1>A faster way to fill your catalog.</h1><p>Preview and validate up to 500 CSV rows before creating unpublished product variants.</p></div><a class="btn light" href="/business/catalog/export">Export catalog CSV</a></div><div class="card"><h3>Upload a CSV</h3><p style="font-size:12px">Columns in this exact order: name,slug,sku,size,color,price_poisha,cost_poisha,fabric. Duplicate SKUs are rejected. Prices are integer poisha. No stock is created by importing.</p><a href="/samples/catalog.csv">Download sample CSV ↗</a><form action="/business/catalog/preview" method="post" enctype="multipart/form-data" class="space-top">@csrf<div class="field"><label for="file">CSV file (maximum 1 MB)</label><input id="file" type="file" name="file" accept=".csv,.txt" required></div><button>Validate & preview</button></form></div>@if($preview)<div class="panel space-top"><div class="panel-heading"><h3>{{ count($preview['rows']) }} valid rows · {{ count($preview['errors']) }} errors</h3></div><div class="panel-body">@if($preview['errors'])<div class="notice error">@foreach($preview['errors'] as $error)<p>{{ $error }}</p>@endforeach</div>@endif<div class="table-wrap"><table><tr><th>{{ __('Name') }}</th><th>SKU</th><th>Size / color</th><th>{{ __('Price') }}</th></tr>@foreach($preview['rows'] as $row)<tr><td>{{ $row['name'] }}</td><td>{{ $row['sku'] }}</td><td>{{ $row['size'] }} / {{ $row['color'] }}</td><td>@money($row['price_poisha'])</td></tr>@endforeach</table></div>@if(!$preview['errors'] && count($preview['rows']))<form action="/business/catalog/commit" method="post">@csrf<button class="space-top">Import {{ count($preview['rows']) }} variants</button></form>@endif</div></div>@endif @endsection